import csv, collections
rows=list(csv.DictReader(open('/app/input/letter_lines.csv')))
out=list(csv.DictReader(open('/app/letter_line_review.csv')))
mixed=[]
for s in sorted(set(r['subject'] for r in rows)):
    by_pos=collections.defaultdict(list)
    for r,o in zip(rows,out):
        if r['subject']==s:
            by_pos[r['position']].append((r['line_id'], o['verdict'], r['wording']))
    for p,items in by_pos.items():
        verdicts=set(v for _,v,_ in items)
        if len(verdicts)>1:
            mixed.append((s,p,items))
print('mixed subject/position groups:', len(mixed))
for s,p,items in mixed:
    print(f'\n### {s} | {p}')
    for line_id,v,w in items:
        print(f'{line_id} | {v} | {w}')
