for s in sorted(set(r['subject'] for r in rows)):
    print(f'\n### {s}')
    groups=collections.defaultdict(list)
    for r,o in zip(rows,out):
        if r['subject']==s:
            groups[r['position']].append((r['line_id'], o['verdict'], o['record_entry'], r['wording']))
    for p,items in sorted(groups.items()):
        print(f"{p} -> {items[0][1]} ({items[0][2]}) | {items[0][3]}")
        if len(items)>1:
            print(f"  ... {len(items)} rows total, ids: {', '.join(i[0] for i in items)}")
print('\nchildren_named rows with digits:')
for r,o in zip(rows,out):
    if r['subject']=='children_named' and any(ch.isdigit() for ch in r['wording']):
        print(f"{r['line_id']} | {o['verdict']} | {r['position']} | {r['wording']}")
